test('upstream model mapping rejection records image-call origin without retry or model override', async () => {
  let calls = 0;
  const provider = createProvider({
    image: {
      generate: async (p, o) => {
        calls++;
        assert(!('model' in (o.extraBody || {})));
        throw Error('400 {"error":{"code":"CUSTOM_MODEL_MAPPING_REQUIRED"}}');
      }
    }
  }, core);
  await assert.rejects(provider.generate({
    prompt: 'image',
    options: {}
  }, {
    id: 'bad'
  }, async () => {}), e => e.source === 'tavo.image.generate' && e.code === 'CUSTOM_MODEL_MAPPING_REQUIRED' && e.details.includes('400'));
  assert.equal(calls, 1);
});
test('metadata reveals discarded actor fields and fixed-seed mismatch without equating metadata to image quality', () => {
  const provider = createProvider({}, core),
    p = {
      scene: '1girl, cafe',
      characters: [{
        name: 'A',
        form: 'default',
        identity: 'girl, black hair',
        equipment: {
          "HEAD": null,
          "TOP": null,
          "LOWER": null,
          "FULL": [{
            "name": "red coat",
            "state": "",
            "visible": true,
            "covers": ["TOP", "LOWER"]
          }],
          "LEGWEAR": null,
          "FOOTWEAR": null,
          "HAND": null,
          "ACCESSORIES": null
        }
      }]
    },
    compiled = core.compose(p, {}, {
      format: 'nai45',
      seedFixed: true,
      seedValue: '5'
    });
  const ignored = {
    hasPrompt: true,
    prompt: '1girl, cafe',
    characterPrompts: []
  };
  const result = provider.verify(compiled, ignored, 99);
  assert.equal(result.status, 'mismatch');
  assert.equal(result.missing.length, 2);
  assert.equal(result.seedMismatch, true);
  assert.equal(provider.verify(compiled, {
    hasPrompt: true,
    prompt: compiled.prompt
  }, 5).status, 'prompt-fields-confirmed');
  assert.equal(provider.verify(compiled, null, null).status, 'unknown');
});
test('official NAI pipe syntax is retained and absent character metadata is informational', () => {
  const provider = createProvider({}, core),
    plan = {
      scene: '2 people, park',
      characters: [{
        name: 'A',
        identity: 'woman, black hair',
        equipment: {
          "HEAD": null,
          "TOP": null,
          "LOWER": null,
          "FULL": [{
            "name": "red coat",
            "state": "",
            "visible": true,
            "covers": ["TOP", "LOWER"]
          }],
          "LEGWEAR": null,
          "FOOTWEAR": null,
          "HAND": null,
          "ACCESSORIES": null
        }
      }, {
        name: 'B',
        identity: 'man, brown hair',
        equipment: {
          "HEAD": null,
          "TOP": [{
            "name": "blue jacket",
            "state": "",
            "visible": true
          }],
          "LOWER": null,
          "FULL": null,
          "LEGWEAR": null,
          "FOOTWEAR": null,
          "HAND": null,
          "ACCESSORIES": null
        }
      }]
    },
    compiled = core.compose(plan, {}, {
      format: 'nai45'
    }),
    result = provider.verify(compiled, {
      hasPrompt: true,
      prompt: compiled.prompt,
      baseCaption: compiled.prompt,
      characterPrompts: []
    }, 42);
  assert.equal(result.status, 'prompt-fields-confirmed');
  assert.equal(result.characterPromptSyntax, 'nai45-pipe');
  assert.equal(result.visualConsistency, 'not-evaluated');
  assert.equal(result.isolationUnconfirmed, true);
  assert.equal(result.warning, '');
  assert.equal(result.notes.length, 1);
  assert(!('v4_prompt' in compiled.options.extraBody));
  assert.equal(compiled.prompt.split(' | ').length, 3);
});
